#include <thread>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::thread::id empty;
    assert(empty == std::thread::id{});
    std::thread worker([] {});
    assert(worker.get_id() != empty);
    std::thread moved;
    moved = std::move(worker);
    moved.join();
}
